extends SceneTree
## Area 4e's probe (spec_4e A, C, E). On office_proportion_test's eight seeds:
## each row's floor median against its band + 2, the main piece and the free
## floor in the frame, the archive's salon cells apart from its one-room units,
## the mobile archives, the papers' tops per planta (and the rooms whose tops
## did not come back), the director's lounge, the runs that join or overlap and
## the near chairs. On office_test's 64 runs: generate()'s time on seeds 1 to 40,
## the floors of last resort, the sure pieces' shares (office_test.floor_recipes())
## and the toilets. Last, criterion C against the base and the last step kept.
## Every line it prints starts with P4E_.
const GEN := preload("res://game/world/generation/office_generator.gd")
const WATCHED := preload("res://evidence/4e_probe_gen.gd")
const OFFICE := preload("res://game/floors/palettes/office_palette.gd")
const FLOOR := preload("res://game/world/generation/floor_definition.gd")
const LAYOUT := preload("res://game/world/generation/office_layout.gd")
const RECIPES := preload("res://game/world/generation/office_recipes.gd")
const FRAMING := preload("res://tools/capture/room_framing.gd")
const PAPERS := preload("res://game/world/generation/document_placement.gd")
const PROP := preload("res://tests/office/office_proportion_test.gd")
## The margin over each row's least floor that spec_4e A aims at.
const MARGIN := 2.0
## The P4E_ lines of the area's base (U01) and of the last step kept.
const BASE := "res://evidence/4e_probe_base.txt"
const PREV := "res://evidence/4e_probe_prev.txt"

var said: Array = []
var thin: Array = []
var fallen_8: Array = []
var fallen_40: Array = []
var fallen_big: Array = []
var overlaps: Array = []

func _initialize() -> void:
	eight()
	sixty_four()
	verdict()
	quit()

func say(line: String) -> void:
	print(line)
	said.append(line)

func eight() -> void:
	var test = PROP.new()
	var floors := {}
	var frees := {}
	var widths := {}
	for row in test.rows:
		floors[row[0]] = []
		frees[row[0]] = []
		widths[row[0]] = []
	var salon: Array = []
	var single: Array = []
	var by_side := {}
	var mobiles := 0
	var long_doors := 0
	var both_ends := 0
	var lounge := {"salas": 0, "mueble": 0, "esquina": 0}
	var joined := 0
	var joinable := 0
	var tables := 0
	var near_seated := 0
	var tops_least := 1000
	for seed_value in PROP.SEEDS:
		var gen = WATCHED.new()
		var m: Dictionary = gen.generate(int(seed_value), 2)
		if m.is_empty() or bool(m.get("fallback", false)):
			fallen_8.append(seed_value)
			continue
		for row in test.rows:
			var name_of := String(row[0])
			for room in m.rooms:
				if (row[1] as Array).has(int(room.type)) and not FLOOR.is_void(room): floors[name_of].append(PROP.floor_taken(room, test.things_of(m, room)))
			var framed: Dictionary = PROP.first_room(m, row[4])
			if framed.is_empty(): continue
			var camera: Dictionary = PROP.camera_of(FRAMING.view_of(framed, FRAMING.door_of(m.rooms, framed)))
			frees[name_of].append(PROP.free_in_frame(camera, test.open_cells(m, framed)))
			if not (name_of in ["electrico", "climatizacion"] or PROP.MAIN_KINDS.has(name_of)): continue
			var main: Array = test.things_of(m, framed).filter(func(thing): return String(thing.what) == "board" or String(thing.what) == "handler" or (PROP.MAIN_KINDS.get(name_of, []) as Array).has(String(thing.what)))
			widths[name_of].append(PROP.width_in_frame(camera, framed, main))
		for room in m.rooms:
			if FLOOR.is_void(room): continue
			var t := int(room.type)
			if t == OFFICE.ARCHIVE:
				if int(room.hall) >= 0: salon.append(PROP.floor_taken(room, test.things_of(m, room)))
				else: single.append(PROP.floor_taken(room, test.things_of(m, room)))
			if t == OFFICE.MOBILE_ARCHIVE:
				var side := snappedf(minf(float(room.span_x), float(room.span_z)), 0.5)
				if not by_side.has(side): by_side[side] = []
				by_side[side].append(PROP.floor_taken(room, test.things_of(m, room)))
			if t == OFFICE.EXEC_OFFICE:
				lounge.salas = int(lounge.salas) + 1
				if room.get("furniture", []).any(func(it): return String(it.kind) == "lounge"): lounge.mueble = int(lounge.mueble) + 1
				if room.get("props", []).any(func(p): return String(p.kind) == "armchair"): lounge.esquina = int(lounge.esquina) + 1
		for unit in m.get("archives", []):
			if not bool(unit.mobile): continue
			mobiles += 1
			var walls: Array = FLOOR.doorways(m.rooms[int(unit.rooms[0])]).map(func(way): return String(way.wall))
			var along_x: bool = String(unit.axis) == "x"
			var long_walls: Array = ["north", "south"] if along_x else ["west", "east"]
			var ends: Array = ["west", "east"] if along_x else ["north", "south"]
			if walls.any(func(w): return long_walls.has(w)): long_doors += 1
			if walls.has(ends[0]) and walls.has(ends[1]): both_ends += 1
		# The papers' tops as office_proportion_test counts them: past document_placement's least.
		var reach_of := {}
		var least_of := {}
		for planta in 3:
			var metres := FLOOR.route_metres(m, FLOOR.entry_of(m, planta))
			var deepest := 0.0
			for id in metres: deepest = maxf(deepest, float(metres[id]))
			reach_of[planta] = metres
			least_of[planta] = maxf(PAPERS.MIN_FROM_START, deepest * PAPERS.SHARE_IN)
		var tops := [0, 0, 0]
		var ceded: Array = []
		for room in m.rooms:
			if FLOOR.is_void(room) or m.refuges.has(int(room.id)) or bool(room.get("landing", false)): continue
			var planta := int(room.wing)
			if float(reach_of[planta].get(int(room.id), 0.0)) >= float(least_of[planta]):
				var had: int = (gen.before.get(int(room.id), []) as Array).filter(func(k): return PAPERS.SURFACES.has(String(k))).size()
				var kept: int = room.get("props", []).filter(func(p): return PAPERS.SURFACES.has(String(p.kind))).size()
				tops[planta] += kept
				if had > kept: ceded.append("planta=%d sala=%d tipo=%s cedidas=%d" % [planta, int(room.id), String(OFFICE.TYPES[int(room.type)]), had - kept])
			if int(room.type) in [OFFICE.OPEN_OFFICE, OFFICE.CUBICLES]: continue
			var items: Array = room.get("furniture", [])
			if int(room.type) == OFFICE.BOARDROOM and items.any(func(it): return String(it.kind).begins_with("meeting_table")):
				tables += 1
				if items.any(func(it): return String(it.kind) == "table_chair"): near_seated += 1
			for i in items.size():
				for j in range(i + 1, items.size()):
					if int(items[i].extra.group) == int(items[j].extra.group) and LAYOUT.footprint(items[i]).grow(-0.01).intersects(LAYOUT.footprint(items[j])): overlaps.append("%d:%d" % [int(seed_value), int(room.id)])
			if test.run_types.has(int(room.type)) and int(room.get("hall", -1)) < 0:
				joinable += 1
				if PROP.joined_kinds(items): joined += 1
		say("P4E_TOPS seed=%d plantas=%s" % [int(seed_value), str(tops)])
		for line in ceded: say("P4E_CEDED seed=%d %s" % [int(seed_value), String(line)])
		tops_least = mini(tops_least, int(tops.min()))
	say("P4E_FALLBACK_8 %s" % str(fallen_8))
	for row in test.rows:
		var name_of := String(row[0])
		var taken: float = PROP.median(floors[name_of])
		var most: float = 100.0 if PROP.NO_CAP.has(name_of) else PROP.MOST_FLOOR
		var measured: bool = name_of in ["electrico", "climatizacion"] or PROP.MAIN_KINDS.has(name_of)
		var piece: float = PROP.median(widths[name_of]) if measured else -1.0
		say("P4E_FLOOR %s salas=%d mediana=%.1f banda=%.0f objetivo=%.0f margen=%+.1f tope=%.0f" % [name_of, (floors[name_of] as Array).size(), taken, float(row[2]), float(row[2]) + MARGIN, taken - float(row[2]) - MARGIN, most])
		say("P4E_FRAME %s pieza=%.1f libre=%.1f libre_max=%.0f muestras=%d" % [name_of, piece, PROP.median(frees[name_of]), float(row[3]), (frees[name_of] as Array).size()])
	say("P4E_ARCHIVE salon_celdas=%d salon_mediana=%.1f sala_celdas=%d sala_mediana=%.1f" % [salon.size(), PROP.median(salon), single.size(), PROP.median(single)])
	say("P4E_MOBILE unidades=%d puerta_larga=%d dos_puertas=%d" % [mobiles, long_doors, both_ends])
	for side in by_side: say("P4E_MOBILE_SIDE corto=%.1f salas=%d mediana=%.1f" % [float(side), (by_side[side] as Array).size(), PROP.median(by_side[side])])
	say("P4E_LOUNGE salas=%d mueble=%d esquina=%d" % [int(lounge.salas), int(lounge.mueble), int(lounge.esquina)])
	say("P4E_TOPS_LEAST minimo=%d" % tops_least)
	say("P4E_RUNS juntos=%d total=%d" % [joined, joinable])
	say("P4E_CHAIRS cerca=%d total=%d" % [near_seated, tables])
	say("P4E_OVERLAPS n=%d %s" % [overlaps.size(), str(overlaps.slice(0, 5))])
	test.free()

func sixty_four() -> void:
	var pairs: Array = []
	for run_seed in range(1, 41): pairs.append([run_seed, 2])
	for run_seed in range(41, 47):
		for survivors in [1, 3, 4, 5]: pairs.append([run_seed, survivors])
	var times: Array = []
	var tally := {"rooms": 0, "sure": 0, "whole": 0, "featureless": 0, "types": {}}
	var kinds := {}
	var toilets := {"salas": 0, "sin_cabinas": 0, "sin_taquillas": 0, "sin_banco": 0}
	for pair in pairs:
		var run_seed := int(pair[0])
		var survivors := int(pair[1])
		var generator = GEN.new()
		var began := Time.get_ticks_msec()
		var m: Dictionary = generator.generate(run_seed, survivors)
		var ms := Time.get_ticks_msec() - began
		if run_seed <= 40: times.append(ms)
		# As office_test: a floor of last resort, or with 4 or 5 one that numbered badly.
		var numbering: bool = generator.stats.keys().any(func(key): return String(key).begins_with("numbered_"))
		if m.is_empty() or bool(m.get("fallback", false)):
			if survivors >= 4: fallen_big.append("%d/%d" % [run_seed, survivors])
			elif run_seed <= 40: fallen_40.append(run_seed)
			continue
		if survivors >= 4 and numbering: fallen_big.append("%d/%d numbered" % [run_seed, survivors])
		floor_recipes(m, tally, kinds, toilets)
	times.sort()
	say("P4E_TIME mediana=%d media=%d" % [int(times[times.size() / 2]), int(PROP.mean(times))])
	say("P4E_FALLBACK_40 %s" % str(fallen_40))
	say("P4E_FALLBACK_BIG %s" % str(fallen_big))
	say("P4E_SURE whole=%d sure=%d pct=%.1f" % [int(tally.whole), int(tally.sure), 100.0 * float(tally.whole) / maxf(float(tally.sure), 1.0)])
	for type_id in tally.types:
		var each: Dictionary = tally.types[type_id]
		var type_name := String(OFFICE.TYPES[int(type_id)])
		say("P4E_SURE_TYPE %s whole=%d rooms=%d" % [type_name, int(each.whole), int(each.rooms)])
		if int(each.rooms) >= 4 and int(each.whole) * 2 < int(each.rooms): thin.append("%s %d de %d" % [type_name, int(each.whole), int(each.rooms)])
	say("P4E_THIN %s" % str(thin))
	say("P4E_FEATURELESS sin=%d salas=%d" % [int(tally.featureless), int(tally.rooms)])
	for type_id in kinds:
		var of_type: Dictionary = kinds[type_id]
		for kind in of_type.have:
			say("P4E_KIND %s %s %d de %d (%.0f%%) dos=%d" % [String(OFFICE.TYPES[int(type_id)]), String(kind), int(of_type.have[kind]), int(of_type.rooms), 100.0 * float(of_type.have[kind]) / maxf(float(of_type.rooms), 1.0), int(of_type.two[kind])])
	say("P4E_TOILETS salas=%d sin_cabinas=%d sin_taquillas=%d sin_banco=%d" % [int(toilets.salas), int(toilets.sin_cabinas), int(toilets.sin_taquillas), int(toilets.sin_banco)])

## office_test.floor_recipes()'s count of the sure pieces, line for line, plus
## each recipe kind's presence in its type's head cells (once per kind, and the
## cells with two or more) and the toilets' pieces.
func floor_recipes(m: Dictionary, tally: Dictionary, kinds: Dictionary, toilets: Dictionary) -> void:
	var rooms: Array = m.rooms
	var by_type: Dictionary = tally.types
	var heads := RECIPES.hall_heads(rooms)
	for room in rooms:
		if int(room.type) == OFFICE.VOID or bool(room.corridor): continue
		var t := int(room.type)
		var id := int(room.id)
		var furniture: Array = room.get("furniture", [])
		var recipe: Array = OFFICE.ROOM_FURNITURE.get(t, [])
		if recipe.is_empty(): continue
		tally.rooms = int(tally.rooms) + 1
		if String(room.get("feature", "")) == "": tally.featureless = int(tally.featureless) + 1
		var have := {}
		for it in furniture: have[String(it.kind)] = true
		var head := int(heads.get(int(room.hall), id))
		var once: Array = OFFICE.ONE_PER_HALL.get(t, []) if head != id else []
		var sure: Array = []
		for entry in recipe:
			if int(entry[2]) >= 1 and not ["lattice", "table", "closed", "spare", "hall"].has(String(entry[1])) and not once.has(String(entry[0])): sure.append(String(entry[0]))
		var whole: bool = sure.all(func(kind): return have.has(kind))
		if not by_type.has(t): by_type[t] = {"rooms": 0, "whole": 0}
		var each: Dictionary = by_type[t]
		if head == id:
			each.rooms = int(each.rooms) + 1
			if whole: each.whole = int(each.whole) + 1
			if not kinds.has(t): kinds[t] = {"rooms": 0, "have": {}, "two": {}}
			var of_type: Dictionary = kinds[t]
			of_type.rooms = int(of_type.rooms) + 1
			var seen := {}
			for entry in recipe:
				var kind := String(entry[0])
				if seen.has(kind): continue
				seen[kind] = true
				if not of_type.have.has(kind):
					of_type.have[kind] = 0
					of_type.two[kind] = 0
				if have.has(kind): of_type.have[kind] = int(of_type.have[kind]) + 1
				if furniture.filter(func(it): return String(it.kind) == kind).size() >= 2: of_type.two[kind] = int(of_type.two[kind]) + 1
		if not sure.is_empty():
			tally.sure = int(tally.sure) + 1
			if whole: tally.whole = int(tally.whole) + 1
		if t == OFFICE.TOILETS:
			toilets.salas = int(toilets.salas) + 1
			if not have.has("cubicles"): toilets.sin_cabinas = int(toilets.sin_cabinas) + 1
			if not have.has("locker_bank"): toilets.sin_taquillas = int(toilets.sin_taquillas) + 1
			if not have.has("bench_slat"): toilets.sin_banco = int(toilets.sin_banco) + 1

## The lines of a file that start with P4E_; none if there is no file.
static func lines_of(path: String) -> Array:
	var out: Array = []
	if not FileAccess.file_exists(path): return out
	for line in FileAccess.get_file_as_string(path).split("\n"):
		if line.strip_edges().begins_with("P4E_"): out.append(line.strip_edges())
	return out

## Lines by their key, the family and the name before the first pair
## ("FLOOR aseos", "TIME"): their name=value pairs, as numbers.
static func values_of(lines: Array) -> Dictionary:
	var out := {}
	for line in lines:
		var words := String(line).split(" ", false)
		var key := words[0].trim_prefix("P4E_")
		var start := 1
		if words.size() > 1 and not words[1].contains("="):
			key += " " + words[1]
			start = 2
		var pairs := {}
		for k in range(start, words.size()):
			var pair := words[k].split("=")
			if pair.size() == 2: pairs[pair[0]] = pair[1].to_float()
		out[key] = pairs
	return out

## Criterion C (encargos 4e), point by point: OK, or FAIL with what broke it.
## e, h, i and k need the base; j, the last step kept.
func verdict() -> void:
	var now := values_of(said)
	var base := values_of(lines_of(BASE))
	var prev := values_of(lines_of(PREV))
	var bad := {}
	for point in ["a", "b", "c", "d", "e", "f", "g", "h", "i", "j", "k", "l"]: bad[point] = []
	var sure: Dictionary = now["SURE"]
	if int(sure.whole) * 4 < int(sure.sure) * 3: bad["a"].append("%d de %d" % [int(sure.whole), int(sure.sure)])
	if not thin.is_empty(): bad["b"].append(str(thin))
	var bare: Dictionary = now["FEATURELESS"]
	if int(bare.sin) * 10 > int(bare.salas): bad["c"].append("%d de %d" % [int(bare.sin), int(bare.salas)])
	for fallen: Array in [fallen_8, fallen_40, fallen_big]:
		if not fallen.is_empty(): bad["d"].append(str(fallen))
	if base.has("TIME") and float(now["TIME"].mediana) > 1.1 * float(base["TIME"].mediana): bad["e"].append("%d frente a %d" % [int(now["TIME"].mediana), int(base["TIME"].mediana)])
	var runs: Dictionary = now["RUNS"]
	if int(runs.total) == 0 or int(runs.juntos) * 2 < int(runs.total): bad["f"].append("tramos %d de %d" % [int(runs.juntos), int(runs.total)])
	var chairs: Dictionary = now["CHAIRS"]
	if int(chairs.total) == 0 or int(chairs.cerca) * 5 < int(chairs.total) * 4: bad["f"].append("sillas %d de %d" % [int(chairs.cerca), int(chairs.total)])
	if base.has("TOILETS") and int(now["TOILETS"].sin_cabinas) > int(base["TOILETS"].sin_cabinas): bad["h"].append("%d frente a %d" % [int(now["TOILETS"].sin_cabinas), int(base["TOILETS"].sin_cabinas)])
	if prev.has("TOPS_LEAST") and int(now["TOPS_LEAST"].minimo) < int(prev["TOPS_LEAST"].minimo): bad["j"].append("mesas %d frente a %d" % [int(now["TOPS_LEAST"].minimo), int(prev["TOPS_LEAST"].minimo)])
	if not overlaps.is_empty(): bad["l"].append(str(overlaps.slice(0, 5)))
	for key in now:
		var k := String(key)
		var v: Dictionary = now[key]
		if k.begins_with("FLOOR ") and int(v.salas) > 0:
			var name_of := k.trim_prefix("FLOOR ")
			if float(v.mediana) > float(v.tope): bad["g"].append("%s suelo %.1f" % [name_of, float(v.mediana)])
			if base.has(k) and float(base[k].mediana) >= float(base[k].banda) and float(v.mediana) < float(v.banda): bad["i"].append("%s %.1f bajo %.0f" % [name_of, float(v.mediana), float(v.banda)])
			if prev.has(k) and float(prev[k].margen) >= 0.0 and float(v.margen) < 0.0: bad["j"].append("%s margen %+.1f" % [name_of, float(v.margen)])
		if k.begins_with("FRAME "):
			var name_of := k.trim_prefix("FRAME ")
			if float(v.libre) > float(v.libre_max): bad["g"].append("%s libre %.1f" % [name_of, float(v.libre)])
			if base.has(k) and float(base[k].pieza) >= 30.0 and float(v.pieza) < 30.0: bad["k"].append("%s pieza %.1f" % [name_of, float(v.pieza)])
	var green := true
	for point in bad:
		var broke: Array = bad[point]
		if broke.is_empty():
			say("P4E_C %s OK" % point)
			continue
		green = false
		say("P4E_C %s FAIL %s" % [point, "; ".join(PackedStringArray(broke))])
	if base.is_empty(): say("P4E_C_NOTA sin base: e, h, i y k sin comprobar")
